<?php
require_once '/var/www/html/wp-load.php';
$ids=get_posts(['post_type'=>'product','post_status'=>['publish','draft','pending','private'],'posts_per_page'=>-1,'fields'=>'ids']);$rows=[];$byBrand=[];$byCat=[];
foreach($ids as $id){$p=wc_get_product($id);if(!$p)continue;$state=(string)get_post_meta($id,'_bhc_catalog_quality_state',true);$ready=(string)get_post_meta($id,'_bhc_release_state',true);if($ready==='ready_for_release')continue;$brand=wp_get_post_terms($id,'pa_brand',['fields'=>'names']);$cat=wp_get_post_terms($id,'product_cat',['fields'=>'names']);$b=$brand[0]??'بدون برند';$c=$cat[0]??'بدون دسته';$sourceStatus=(string)get_post_meta($id,'_bhc_source_audit_status',true);$source=(string)get_post_meta($id,'_bhc_source_url',true);$imageStatus=(string)get_post_meta($id,'_bhc_image_generation_status',true);$reason=$state==='reference_invalid'?'مدل/مرجع نامعتبر و قرنطینه‌شده':($sourceStatus==='reviewed_no_exact_source'?'منبع دقیق پیدا نشد':'منبع دقیق مدل/پسوند تأیید نشده');$row=['id'=>$id,'sku'=>$p->get_sku(),'model'=>get_post_meta($id,'_bhc_model',true),'name'=>$p->get_name(),'brand'=>$b,'category'=>$c,'catalog_state'=>$state,'release_state'=>$ready,'source_audit_status'=>$sourceStatus,'source_url'=>$source,'image_status'=>$imageStatus,'reason'=>$reason];$rows[]=$row;$byBrand[$b]=($byBrand[$b]??0)+1;$byCat[$c]=($byCat[$c]??0)+1;}
$dir=wp_upload_dir()['basedir'].'/catalog-audits';if(!is_dir($dir))wp_mkdir_p($dir);file_put_contents($dir.'/blocked-catalog-v583.json',wp_json_encode(['generated_at'=>current_time('mysql'),'total'=>count($rows),'by_brand'=>$byBrand,'by_category'=>$byCat,'products'=>$rows],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT));$fp=fopen($dir.'/blocked-catalog-v583.csv','w');fputcsv($fp,array_keys($rows[0]??['id'=>'']));foreach($rows as $r)fputcsv($fp,$r);fclose($fp);echo 'BLOCKED_TOTAL|'.count($rows).PHP_EOL;foreach($byBrand as $k=>$v)echo 'BRAND|'.$k.'|'.$v.PHP_EOL;echo 'JSON|'.$dir.'/blocked-catalog-v583.json'.PHP_EOL.'CSV|'.$dir.'/blocked-catalog-v583.csv'.PHP_EOL;
